INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17001, 'Isaiah 24:17', 'Isaiah', 24, 17, '&nbsp;اے د دُنيا خلقو واورئ. يره، کندې او دامونه ستاسو دپاره تيار دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17002, 'Isaiah 24:18', 'Isaiah', 24, 18, '&nbsp;هر څوک چې د يرې نه تښتېدل غواړى نو هغه به په کنده کښې پرېوځى او هر څوک چې د کندې نه ځان خلاصوى نو په دام کښې به ګېريږى. د آسمان نه به ډېر دروند باران وريږى او د زمکې بنيادونه به ولړزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17003, 'Isaiah 24:19', 'Isaiah', 24, 19, '&nbsp;زمکه به وچوى، خوځيږى به او زنګيږى به.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17004, 'Isaiah 24:20', 'Isaiah', 24, 20, '&nbsp;زمکه به د شرابى نشه کوونکى په شان زنګيږى او داسې رپيږى لکه چې په طوفان کښې چې چوپال خوځيږى. دا د ګناه په وجه درَنه شوې ده، دا به راوغورزيږى او بيا به هيڅکله پا نۀ څى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17005, 'Isaiah 24:21', 'Isaiah', 24, 21, '&nbsp;په هغه وخت به مالِک خُدائ آسمانى طاقتونو له او د زمکې بادشاهانو له به سزا ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17006, 'Isaiah 24:22', 'Isaiah', 24, 22, '&nbsp;هغوئ به ګرفتار کړے شى او په يوه قېدخانه کښې به بند کړے شى او ښۀ موده پس به ورته سزا ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17007, 'Isaiah 24:23', 'Isaiah', 24, 23, '&nbsp;نو سپوږمۍ به توره شى او د نمر رڼا به کمه شى، ځکه چې مالِک خُدائ ربُ الافواج به حکومت کوى. هغه به په يروشلم کښې د صيون په غرۀ باندې د مشرانو په وړاندې شان او شوکت سره بادشاهى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17008, 'Isaiah 25:1', 'Isaiah', 25, 1, '&nbsp;اے مالِکه خُدايه، تۀ زما خُدائ پاک يې، زۀ به ستا درناوے کوم او ستا د نوم ثناء صِفت به کوم. تا عجيبه عجيبه کارونه کړى دى، تا چې ډېر پخوا کومې منصوبې جوړې کړې وې، تا بې‌شکه هغه د وفادارۍ سره پوره کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17009, 'Isaiah 25:2', 'Isaiah', 25, 2, '&nbsp;تا ښارونو نه د ملبو ډيرى جوړ کړى دى، او د هغوئ د پَخو دېوالونو قلعې دې په کنډراتو بدل کړى دى. د پردى مُلک د خلقو د قلعې په شان محلونه داسې خاورې شوى دى چې بيا به هيڅکله ورته ښار ونۀ شى وئيلے او نۀ به کله دوباره آباد کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17010, 'Isaiah 25:3', 'Isaiah', 25, 3, '&nbsp;نو په دې وجه د تکړه قومونو خلق به ستا ثناء صِفت کوى، او د ظالمانو قومونو په ښارونو کښې به ستا نه يره کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17011, 'Isaiah 25:4', 'Isaiah', 25, 4, '&nbsp;تۀ د غريبانانو حفاظت کوونکے يې، او د مصيبت په وخت کښې د ضرورتمندو حِفاظت کوونکے يې. تا هغوئ له د طوفانونو نه پناه ورکړې ده، او د سوزونکى ګرمۍ نه دې سورے ورکړے دے. د ظالمانو پوکى لکه د ژمى د طوفانى باران په شان وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17012, 'Isaiah 25:5', 'Isaiah', 25, 5, '&nbsp;لکه د صحرا د ګرمۍ په شان دى. تا د پردى مُلک خلق غلى کړى دى. تا د ظالمانو خلقو آوازونه داسې خاموش کړى دى، لکه چې وريځې سخته ګرمى يخوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17013, 'Isaiah 25:6', 'Isaiah', 25, 6, '&nbsp;د صيون په غرۀ به مالِک خُدائ ربُ الافواج د دُنيا د ټولو قومونو دپاره يوه مېلمستيا وکړى، دا مېلمستيا به د ښې غوښې او د انګورو د ښو ميو وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17014, 'Isaiah 25:7', 'Isaiah', 25, 7, '&nbsp;نو په دې غر به هغه د خلقو نه د مرګ سورے ختم کړى، کوم سورے چې د ټولو قومونو دپاسه ولاړ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17015, 'Isaiah 25:8', 'Isaiah', 25, 8, '&nbsp;مالِک خُدائ پاک به مرګ د تل دپاره ختم کړى. او د هر يو کس په مخ باندې به اوښکې اوچې کړى او د ټولې دُنيا نه به د خپلو خلقو بې‌عزتى لرې کړى. مالِک خُدائ په خپله دا فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17016, 'Isaiah 25:9', 'Isaiah', 25, 9, '&nbsp;په هغه وخت به هغوئ وائى، ”وګورئ دا دے زمونږ خُدائ پاک. مونږ د هغۀ په انتظار وُو او هغۀ مونږ آزاد کړُو. دا دے هغه مالِک خُدائ د چا چې مونږ په انتظار وُو. راځئ چې د هغۀ په خلاصون باندې د خوشحالۍ جشن وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17017, 'Isaiah 25:10', 'Isaiah', 25, 10, '&nbsp;مالِک خُدائ به د صيون د غرۀ حِفاظت کوى، خو موآب به داسې د پښو لاندې کړے شى لکه چې بوس په غوبل کښې د پښو لاندې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17018, 'Isaiah 25:11', 'Isaiah', 25, 11, '&nbsp;خُدائ پاک به موآب داسې دباؤ کړى لکه څنګه چې لامبوزن اوبۀ خپلو لاسونو سره لاندې ديکه کوى، هغه به د دوئ غرور او د دوئ ټول بد کارونه ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17019, 'Isaiah 25:12', 'Isaiah', 25, 12, '&nbsp;هغه به د موآب د اوچتو دېوالونو والا قلعې تباه کړى او را وبه يې غورزوى او د خاورو سره به يې خاورې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17020, 'Isaiah 26:1', 'Isaiah', 26, 1, '&nbsp;په هغه وخت به د يهوداه په مُلک کښې دا سندره وئيلے شى، ”زمونږ ښار مضبوط دے. ولې چې د خُدائ پاک د خلاصون دېوالونه زمونږ چارچاپيره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17021, 'Isaiah 26:2', 'Isaiah', 26, 2, '&nbsp;د ښار دروازې کولاو کړئ چې صادق قوم ورننوځى، هغه قوم چې وفادار پاتې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17022, 'Isaiah 26:3', 'Isaiah', 26, 3, '&nbsp;د چا ايمان چې مضبوط دے تۀ هغوئ بلکل محفوظ ساتې، ولې چې هغوئ په تا بهروسه ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17023, 'Isaiah 26:4', 'Isaiah', 26, 4, '&nbsp;په مالِک خُدائ باندې تل يقين ساتئ، ولې چې مالِک خُدائ پاک ابدى حِفاظت کوونکے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17024, 'Isaiah 26:5', 'Isaiah', 26, 5, '&nbsp;څوک چې مغروره وُو نو هغۀ عاجزان کړى دى، او هغۀ اوچت ښارونه راګزار کړى دى او خاورو سره يې خاورې کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17025, 'Isaiah 26:6', 'Isaiah', 26, 6, '&nbsp;او دوئ به د غريبانانو او مظلومانو د پښو لاندې راشى او چخڼى به شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17026, 'Isaiah 26:7', 'Isaiah', 26, 7, '&nbsp;اے مالِکه خُدايه، د صادقانو لار هواره ده، نو د صادقانو دپاره چې کومه لار تۀ جوړوې نو هغه نېغه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17027, 'Isaiah 26:8', 'Isaiah', 26, 8, '&nbsp;اے مالِکه خُدايه، ستا فرمانبردارى کولو سره مونږ تا ته خپله بهروسه ښايُو، او زمونږ د زړۀ خواهش دے چې ستا د نوم لوئى وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17028, 'Isaiah 26:9', 'Isaiah', 26, 9, '&nbsp;ټوله شپه زۀ ستا په لټون کښې يم، په سحر کښې د زړۀ د اخلاصه زۀ ستا طلبګار يم، کله چې تۀ د دُنيا د عدالت دپاره راشې نو خلق به پوهه شى چې اِنصاف څۀ څيز دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17029, 'Isaiah 26:10', 'Isaiah', 26, 10, '&nbsp;کۀ په بدعمله باندې رحم وشى نو هغه د اِنصاف په مطلب ځان نۀ پوهوى، بلکې په کوم مُلک کښې چې اِنصاف کيږى هلته هم هغوئ بدعملى کوى، هغوئ د مالِک خُدائ لوئى نۀ منى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17030, 'Isaiah 26:11', 'Isaiah', 26, 11, '&nbsp;اے مالِکه خُدايه، ستا لاس هغوئ ته سزا ورکولو دپاره اوچت شوے دے خو هغوئ هيڅ غور نۀ کوى، او هغوئ چې ستا قوم دپاره ستا غېرت ته وګورى نو وبه شرميږى. او بيا به تۀ سور اور په خپلو دشمنانو نازل کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17031, 'Isaiah 26:12', 'Isaiah', 26, 12, '&nbsp;اے مالِکه خُدايه، تۀ به مونږ له امن راکوې، ځکه چې زمونږ ټولې کاميابۍ ستا د لاسه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17032, 'Isaiah 26:13', 'Isaiah', 26, 13, '&nbsp;اے مالِکه خُدايه، خُدايه پاکه، نورو مالِکانو په مونږ حکمرانى کړې ده، خو يواځې تۀ هغه هستى يې چې مونږ يې عبادت کوُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17033, 'Isaiah 26:14', 'Isaiah', 26, 14, '&nbsp;خو اوس هغوئ مړۀ شوى دى او بيا به نۀ راژوندى کيږى، د هغوئ روحونه به واپس نۀ راځى، ځکه چې تا دوئ له سزا ورکړې ده او تباه کړى دې دى. او د هغوئ نوم او نشان دې ختم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17034, 'Isaiah 26:15', 'Isaiah', 26, 15, '&nbsp;اے مالِکه خُدايه، تا خپل قوم له ترقى ورکړې ده، تا خپل قوم لوئ کړے دے او خپله لوئى دې څرګنده کړې ده. ستا د وجې د هغوئ علاقه په هر طرف باندې خوره شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17035, 'Isaiah 26:16', 'Isaiah', 26, 16, '&nbsp;اے مالِکه خُدايه، چې هغوئ په مصيبت کښې ګېر شول نو ستا تلاش يې شروع کړو او ستا د تنبيه لاندې يې دُعا شروع کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17036, 'Isaiah 26:17', 'Isaiah', 26, 17, '&nbsp;اے مالِکه خُدايه، تا مونږ داسې ژړولى يُو، لکه چې يوه ښځه د بچى د پېدا کېدو د درد په وجه ژاړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17037, 'Isaiah 26:18', 'Isaiah', 26, 18, '&nbsp;مونږ په خوږ او درد مبتلا يُو، خو زمونږ د تکليف نه هيڅ هم پېدا نۀ شول. نۀ مونږ زمکې ته خلاصون ورکړے دے، او نۀ مو دُنيا ته ژوندون راوړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17038, 'Isaiah 26:19', 'Isaiah', 26, 19, '&nbsp;خو زمونږ کوم خلق چې مړۀ شوى دى نو هغه بيا راژوندى شى. د هغوئ مړۀ جسمونه به بيا راژوندى شى. کوم چې په قبرونو کښې پراتۀ دى نو هغه به راپاڅى او د خوشحالۍ سندرې به وائى. لکه څنګه چې د پرخې څاڅکى زمکه تازه کوى، نو داسې به مالِک خُدائ هغه خلق بيا راژوندى کړى کوم چې پخواه مړۀ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17039, 'Isaiah 26:20', 'Isaiah', 26, 20, '&nbsp;زما خلقو، خپلو کورونو ته ننوځئ او په ځان پسې دروازې بندې کړئ. د څۀ وخت دپاره ځانونه پټ کړئ چې د خُدائ پاک غصه سړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17040, 'Isaiah 26:21', 'Isaiah', 26, 21, '&nbsp;وګورئ، مالِک خُدائ په آسمان کښې د خپل اوسېدو ځائ نه راروان دے چې د زمکې خلقو له د هغوئ د ګناه په وجه سزا ورکړى. کومه وينه چې په زمکه باندې تويه شوې وه نو هغه به راښکاره کړے شى او چې څوک وژلى شوى وى نو زمکه به يې نۀ پټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17041, 'Isaiah 27:1', 'Isaiah', 27, 1, '&nbsp;په هغه ورځ به مالِک خُدائ د خپلې زورَورې او کلکې تُورې نه کار واخلى چې هغه تښتېدونکې بلا له يعنې تاوېدونکې راتاوېدونکې بلا له سزا ورکړى او وې ووژنى کومه چې په سمندر کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17042, 'Isaiah 27:2', 'Isaiah', 27, 2, '&nbsp;په هغه ورځ د انګورو ښائسته باغ په حقله سندره ووايئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17043, 'Isaiah 27:3', 'Isaiah', 27, 3, '&nbsp;”زۀ مالِک خُدائ پخپله د دې خيال ساتم او پابندۍ سره اوبۀ ورکوم. او شپه او ورځ د دې څوکيدارى کوم چې څوک نقصان ور ونۀ رسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17044, 'Isaiah 27:4', 'Isaiah', 27, 4, '&nbsp;زما غصه اوس يخه شوې ده. خو کۀ په دې باغ کښې ازغى او مرکونډۍ وشول نو زۀ به ورسره جنګ وکړم او ټول به وسوزوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17045, 'Isaiah 27:5', 'Isaiah', 27, 5, '&nbsp;خو کۀ هغوئ زما نه مدد وغواړى، نو هغوئ دې ما سره روغه وکړى. آو، پرېږدئ چې هغوئ ما سره صُلح وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17046, 'Isaiah 27:6', 'Isaiah', 27, 6, '&nbsp;هغه وخت راروان دے چې د يعقوب اولاد به جرړې وکړى، اِسرائيل به غوټۍ ونيسى او ګلونه به وکړى. او مېوه به يې دُنيا ډکه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17047, 'Isaiah 27:7', 'Isaiah', 27, 7, '&nbsp;ولې مالِک خُدائ اِسرائيل داسې وهلے دے لکه څنګه يې چې د هغۀ دشمنان وهلى دى؟ ولې بنى اِسرائيل داسې قتل شوى دى لکه څنګه چې د هغۀ دشمنان قتل شوى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17048, 'Isaiah 27:8', 'Isaiah', 27, 8, '&nbsp;نه، بلکې مالِک خُدائ د هغوئ مخالفت وکړو او جلاوطن يې کړل. هغوئ يې د نمرخاتۀ په طرف د يوې زورَورې هوا سره وشړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17049, 'Isaiah 27:9', 'Isaiah', 27, 9, '&nbsp;نو داسې به د يعقوب ګناه معاف شى، او چې کله د اِسرائيل ګناهونه ختم شى نو په نتيجه کښې به هغوئ د غېرو قومونو قربان‌ګاه د چونې د کاڼى په شان ذرې ذرې کړى او د قربان‌ګاه خوشبودارې مصالحې او د اشيرې د بُت نښې به پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17050, 'Isaiah 27:10', 'Isaiah', 27, 10, '&nbsp;د قلعې په شان د پَخو دېوالونو ښار کنډر پروت دے. دا د يو خوشى بيابان په شان وران ويجاړ پروت دے. او بيا به په دې کښې څاروى څريږى آرام به کوى او څانګې به خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17051, 'Isaiah 27:11', 'Isaiah', 27, 11, '&nbsp;د ونو څانګې اوچې شوې او ماتې شوې دى او ښځې يې د خشاک په توګه راغونډوى. خلق په هيڅ څيز باندې هم ځان نه پوهوى نو په دې وجه چا چې هغوئ پېدا کړى دى ورباندې هيڅ رحم نۀ کوى، چا چې هغوئ تخليق کړى دى ورباندې هيڅ ترس نۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17052, 'Isaiah 27:12', 'Isaiah', 27, 12, '&nbsp;په هغه ورځ به مالِک خُدائ د فرات سيند نه واخله تر مِصر سرحده پورې خپل خلق يو يو کس راغونډ کړى، داسې لکه څوک چې د بوسو نه غنم رابېلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17053, 'Isaiah 27:13', 'Isaiah', 27, 13, '&nbsp;په هغه وخت به يو بيګل وغږولے شى چې د اسور او مِصر نه هغه ټول بنى اِسرائيليان راوغواړى کوم چې په جلاوطنۍ کښې وى. نو هغوئ به د هغۀ په مقدس غر په يروشلم کښې د مالِک خُدائ عبادت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17054, 'Isaiah 28:1', 'Isaiah', 28, 1, '&nbsp;په سامريه باندې افسوس چې د شرابى بنى اِسرائيلو شاندار تاج دے. په هغه ښار باندې افسوس چې د بنى اِسرائيلو شان او شوکت وو خو اوس مړاوے کېدونکے ګل دے. په هغه آبادۍ باندې افسوس چې په نشه کښې د ډوبو خلقو په زرخيزه وادۍ باندې ولاړه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17055, 'Isaiah 28:2', 'Isaiah', 28, 2, '&nbsp;ګورئ، مالِک خُدائ به داسې قوى او طاقتور لښکر راولېږى، لکه د ږلۍ طوفان او زل زول او د باران د طوفان په شان، دا به لکه د زورَور سېلاب پرې حمله وکړى او په زمکه به يې سر د لاندې راوولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17056, 'Isaiah 28:3', 'Isaiah', 28, 3, '&nbsp;بيا به سامريه د بنى اِسرائيلو شرابيانو شاندار تاج د پښو لاندې ذرې ذرې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17057, 'Isaiah 28:4', 'Isaiah', 28, 4, '&nbsp;بيا به د دې مړاوے کېدونکے ګل شان او شوکت ختم شى چې په زرخيزه وادۍ باندې ولاړ وى. د هغوئ حال د موسم د وړومبو اينځرو په شان دے چې څنګه پاخۀ شى نو راوشوکولے شى او وخوړلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17058, 'Isaiah 28:5', 'Isaiah', 28, 5, '&nbsp;په هغه ورځ به مالِک خُدائ ربُ الافواج د خپلو هغه خلقو دپاره د ګلونو د شاندار تاج په شان وى چې کوم خلق ژوندى پاتې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17059, 'Isaiah 28:6', 'Isaiah', 28, 6, '&nbsp;هغه به هغه کسانو له د اِنصاف جذبه ورکړى چې څوک د قاضيانو په توګه کار کوى او هغوئ له به حوصله ورکړى چې څوک د حملې نه د ښار د دروازو حِفاظت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17060, 'Isaiah 28:7', 'Isaiah', 28, 7, '&nbsp;نو بيا پېغمبران او اِمامان هم دومره نشه دى تر دې پورې چې ډغرې وهى. هغوئ مے او شراب دومره زيات څښلى دى چې تيندکونه خورى. پېغمبران دومره زيات نشه دى چې خُدائ پاک کومه وحى نازلوى نو په هغې باندې نۀ پوهيږى او اِمامان هم دومره نشه دى چې د فېصلې ورکولو په وخت زنګيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17061, 'Isaiah 28:8', 'Isaiah', 28, 8, '&nbsp;د هغوئ ټول مېزونه په اولټو ګنده دى او يو ځائ هم په کښې صفا نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17062, 'Isaiah 28:9', 'Isaiah', 28, 9, '&nbsp;هغوئ په خپلو کښې وائى، ”دا سړے زمونږ سره دا رنګ خبرې ولې کوى؟ د تعليم او د مالِک خُدائ د پېغام اورولو په وخت مونږ داسې پوهوى لکه چې مونږ واړۀ ماشومان يُو او اوس اوس د پيو نه خلاص شوى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17063, 'Isaiah 28:10', 'Isaiah', 28, 10, '&nbsp;هغه مونږ ته ټکے په ټکے، کرښه په کرښه او په مزه مزه تعليم راکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17064, 'Isaiah 28:11', 'Isaiah', 28, 11, '&nbsp;نو اوس به خُدائ پاک خپلو خلقو سره د پردى مُلک د خلقو په ذريعه خبرې کوى څوک چې عجيبه ژبه وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17065, 'Isaiah 28:12', 'Isaiah', 28, 12, '&nbsp;خُدائ پاک خپلو خلقو ته فرمائيلى دى، ”دا د آرام ځائ دے. ستړى دې دلته آرام وکړى، ولې چې هم دا ځائ د آرام دے.“ خو هغوئ غوږ نۀ کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17066, 'Isaiah 28:13', 'Isaiah', 28, 13, '&nbsp;نو دا ځکه به مالِک خُدائ هغوئ ته ټکے په ټکے، کرښه په کرښه او په مزه مزه تعليم ورکوى. نو هغوئ به تيندکونه وخورى او راپرې به وځى. هغوئ به زخمى شى، په جال کښې به ګېر شى او ګرفتار به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17067, 'Isaiah 28:14', 'Isaiah', 28, 14, '&nbsp;نو اے ګستاخه کسانو څوک چې په يروشلم کښې په دې خلقو باندې حکومت کوئ، اوس چې څۀ مالِک خُدائ فرمائى نو هغې ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17068, 'Isaiah 28:15', 'Isaiah', 28, 15, '&nbsp;تاسو لافې وهلې چې تاسو د مرګ سره لوظ کړے دے او د عالمِ ارواح سره مو تړون کړے دے. ستاسو دا يقين دے چې کله افت راشى نو تاسو به بچ شئ، ځکه چې ستاسو خيال دا دے چې خپل دروغ او دوکه به تاسو بچ وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17069, 'Isaiah 28:16', 'Isaiah', 28, 16, '&nbsp;نو مالِک خُدائ پاک داسې فرمائى، ”زۀ په صيون کښې يو داسې بنياد ږدم چې کلک او مضبوط وى. په هغې کښې زۀ د ګوټ يو قيمتى کاڼے لګوم چې په هغې باندې دا ليکلى وى، ”څوک چې ايمان لرى نو هغه به نۀ وارخطا کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17070, 'Isaiah 28:17', 'Isaiah', 28, 17, '&nbsp;زۀ به اِنصاف د دې فيته او صداقت د دې د سال مزے کړم. تاسو چې په کومو دروغو باندې يقين ساتئ نو ږلۍ به يې ټول يوسى او سېلابونه به ستاسو د پناه ځايونه وران کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17071, 'Isaiah 28:18', 'Isaiah', 28, 18, '&nbsp;تاسو چې د مرګ سره کوم لوظ کړے دے نو هغه به منسوخ کړے شى او چې د عالمِ ارواح سره تاسو کوم تړون کړے وى نو هغه به ختم کړے شى. هغه زورَور افت به تاسو ووهى او تاسو به ترې نه لاندې شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17072, 'Isaiah 28:19', 'Isaiah', 28, 19, '&nbsp;دا افت به تاسو بار بار وهى او هر سحر به مو وهى. دا به په تاسو شپه او ورځ راځى، تر هغې پورې چې تاسو يې وړى نۀ يئ. دا پېغام به ستاسو په خلقو باندې يره راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17073, 'Isaiah 28:20', 'Isaiah', 28, 20, '&nbsp;ستاسو کټ دومره لنډ دے چې پښې په کښې نۀ شى غزېدلے او کمبله دومره وړه ده چې څوک په کښې پټېدے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17074, 'Isaiah 28:21', 'Isaiah', 28, 21, '&nbsp;مالِک خُدائ به داسې راپاڅى لکه څنګه چې هغه د پراضيم په غر باندې فلستيانو پسې راپاڅېدلے وو. او څنګه يې چې د جبعون په وادۍ کښې اموريانو باندې حمله کړې وه داسې به په تاسو هم حمله وکړى. او چې کوم کارونه به هغه کوى نو هغه به عجيبه وى. او د هغۀ هر قدم به فرق فرق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17075, 'Isaiah 28:22', 'Isaiah', 28, 22, '&nbsp;زۀ چې کوم خبردارے درکوم نو په هغې پورې خندا مۀ کوئ. کۀ تاسو خندا وکړه نو ستاسو دپاره به خلاصېدل نور هم ګران شى. ما د مالِک خُدائ ربُ الافواج د ټول مُلک د تباه کولو فېصله اورېدلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17076, 'Isaiah 28:23', 'Isaiah', 28, 23, '&nbsp;زۀ چې درته څۀ وايم نو هغې ته غوږ ونيسئ، زۀ چې درته څۀ وايم هغې ته ښۀ توجو وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17077, 'Isaiah 28:24', 'Isaiah', 28, 24, '&nbsp;ولې زميدار همېشه يوه کوى او هيڅکله کر نۀ کوى څۀ؟ ولې هغه تل پټې اړوى او هيڅکله څۀ نۀ کَرى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17078, 'Isaiah 28:25', 'Isaiah', 28, 25, '&nbsp;کله چې هغه يو ځل پټے هوار او تيار کړى، نو هغه تخم کَرى لکه کاږۀ، د زېرے تخم، غنم او اوربشې په صحيح طريقه او صحيح ځائ باندې کَرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17079, 'Isaiah 28:26', 'Isaiah', 28, 26, '&nbsp;زميدار ته پته وى چې څۀ به کوى، ځکه چې خُدائ پاک هغۀ ته پوهه ورکړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17080, 'Isaiah 28:27', 'Isaiah', 28, 27, '&nbsp;هغه د کاږو او زېرې د تخم ټکولو دپاره لوئ ډانګ نۀ استعمالوى، بلکې د دې دپاره د يو وړوکى او برابر لرګى نه کار اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17081, 'Isaiah 28:28', 'Isaiah', 28, 28, '&nbsp;هغه غنم په درمند کښې دومره نۀ غوبل کوى چې خراب‌تُراب شى، ځکه چې هغۀ ته پته وى چې په ګاډۍ باندې به يې څنګه غوبل کړى چې غله خرابه نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17082, 'Isaiah 28:29', 'Isaiah', 28, 29, '&nbsp;مالِک خُدائ ربُ الافواج زبردست اُستاذ دے، او هغه دې زميدارانو له ښۀ پوهه ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17083, 'Isaiah 29:1', 'Isaiah', 29, 1, '&nbsp;اے ارى‌ايل، ارى‌ايل، په تا باندې افسوس. په هغه ښار باندې افسوس کوم کښې چې داؤد خېمې لګولې وې. اوس کال په کال خپل اخترونه کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17084, 'Isaiah 29:2', 'Isaiah', 29, 2, '&nbsp;خو بيا به زۀ په هغه ښار باندې يو افت راولم، هلته به ژړا او ماتم وى. او ټول يروشلم به داسې شى لکه څنګه چې د هغې د ارى‌ايل نوم معنىٰ ده ”يوه داسې قربان‌ګاه چې په وينو لت پت وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17085, 'Isaiah 29:3', 'Isaiah', 29, 3, '&nbsp;ولې چې زۀ به تا د هر طرف نه راګېر کړم او ستا د محاصرې به پوره بندوبست وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17086, 'Isaiah 29:4', 'Isaiah', 29, 4, '&nbsp;بيا به تۀ د زمکې لاندې نه خبرې کوې، د خاورو نه به ستا غلے آواز راوځى. څنګه چې د يو مړى روح د قبر نه د خبرو کولو کوشش کوى، دغه شان به ستا آواز غلے شان راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17087, 'Isaiah 29:5', 'Isaiah', 29, 5, '&nbsp;نو سمدستى به ستا دشمنان لکه د دوړې په شان والوځى، په تا باندې حمله کوونکى به داسې وشړلے شى لکه هوا چې بوس زغلى. ولې چې اچانک په يوه لحظه کښې به', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17088, 'Isaiah 29:6', 'Isaiah', 29, 6, '&nbsp;مالِک خُدائ ربُ الافواج به ستا د بچ کولو دپاره د لوئ تندر، زلزلې، لوئ شور، تېزې سيلۍ، طوفان او سوزونکى اور سره راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17089, 'Isaiah 29:7', 'Isaiah', 29, 7, '&nbsp;نو بيا د هغه ټولو قومونو لښکرې کوم چې د خُدائ پاک د ارى‌ايل په ښار باندې حمله کوى، د هغوئ ټوله وسله او ساز و سامان به د يو خوب ليدو په شان فنا شى، داسې به فنا شى لکه چې دا د شپې يو خيال وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17090, 'Isaiah 29:8', 'Isaiah', 29, 8, '&nbsp;هغه ټول قومونه چې په يروشلم باندې د حملې کولو دپاره راجمع شوى دى د هغوئ مثال به د يو اوږى کس په شان وى چې خوب وينى چې هغه خوراک کوى خو چې راپاڅى نو پته ورته ولګى چې هغه هم هغسې اوږے دے، يا د هغه تږى کس په شان وى چې په خوب کښې ګورى چې اوبۀ څښى خو چې راپاڅى نو پته ورته ولګى چې هغه هم هغه شان د تندې د لاسه بې‌دمه دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17091, 'Isaiah 29:9', 'Isaiah', 29, 9, '&nbsp;حېران شئ او اريان دريان شئ. ځان نه ړاندۀ جوړ کړئ او ړاندۀ شئ. نشه شئ خو په ميو نه، زنګېږئ خو په شرابو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17092, 'Isaiah 29:10', 'Isaiah', 29, 10, '&nbsp;نو ځکه مالِک خُدائ تاسو خوبَولى کړى يئ او په دروند خوب باندې په اودۀ کېدو بدل يئ. هغۀ د پېغمبرانو او د رويا ليدونکو سترګې بندې کړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17093, 'Isaiah 29:11', 'Isaiah', 29, 11, '&nbsp;د هرې پېغمبرۍ د وحى مطلب به ستاسو نه پټ وى، دا به د يو بند کِتاب په شان وى. کۀ تاسو دا يو داسې کس له يوسئ چې هغه يې لوستلے شى او هغۀ ته ووايئ چې دا ولولى، نو هغه به وائى چې زۀ دا نۀ شم لوستلے ځکه چې دا پوخ بند دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17094, 'Isaiah 29:12', 'Isaiah', 29, 12, '&nbsp;کۀ تاسو دا يو بې‌تعليمه کس له ورکړئ چې وې لولى، نو هغه به جواب درکړى چې زۀ بې‌تعليمه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17095, 'Isaiah 29:13', 'Isaiah', 29, 13, '&nbsp;مالِک خُدائ وفرمائيل، ”دا خلق تش په خولۀ زما عزت کوى خو زړونه يې رانه ډېر لرې دى. او دوئ بې‌فائدې زما عبادت کوى ځکه چې دوئ د انسانانو حُکمونه د تعليم په ډول ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17096, 'Isaiah 29:14', 'Isaiah', 29, 14, '&nbsp;نو په دې وجه به په راتلونکى وخت کښې يو ځل بيا زما سلوک د دې قوم سره ډېر عجيبه او د حېرانتيا وى. بيا به د هغوئ د هوښيارانو هوښيارتيا ختمه شى او د هغوئ د پوهانو پوهه به غېبه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17097, 'Isaiah 29:15', 'Isaiah', 29, 15, '&nbsp;څوک چې د مالِک خُدائ نه د خپلو منصوبو د پټولو کوشش کوى نو په هغوئ افسوس. هغوئ په پټه باندې منصوبې جوړوى او خيال يې دا وى چې، ”څوک به مونږ وينى او څوک به مونږ وپېژنى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17098, 'Isaiah 29:16', 'Isaiah', 29, 16, '&nbsp;هغوئ هر يو څيز ګډ وډ کوى. د کُلال اهميت زيات دے کۀ د خټې؟ يو کس چې څۀ څيز جوړ کړى نو هغه څيز خپل جوړېدونکى ته داسې وائى څۀ، ”تا زۀ نۀ يم جوړ کړے،“ او يا دا چې، ”تۀ په هيڅ هم نۀ پوهېږې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17099, 'Isaiah 29:17', 'Isaiah', 29, 17, '&nbsp;لږ وخت پس به د لبنان ځنګل نه پټى جوړ شى او پټى به په ځنګل بدل شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17100, 'Isaiah 29:18', 'Isaiah', 29, 18, '&nbsp;کله چې هغه وخت راشى، نو کاڼۀ به د کِتاب تلاوت اورى او ړاندۀ به د تورتم او تيارۀ نه رابهر شى او وينى به.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');